INSERT INTO certification_question (id, certification_id, question_text, choice1, choice2, choice3, choice4, answer_no, explanation, created_at, deleted)
VALUES
(2, 1, '상지의 굴곡, 신전 및 외전에 주동적으로 작용하는 근은?', '대흉근', '상완삼두근', '상완이두근', '삼각근', 4, '삼각근은 상지의 굴곡, 신전 및 외전에 주동적으로 작용하는 근입니다.', NOW(), 0),
(3, 1, '혈액의 구성 물질로 외부로부터 침입한 세균 등을 세포 내로 끌여들여 면역 관여와 가장 관계가 깊은 것은?', '백혈구', '적혈구', '혈소판', '혈장', 1, '백혈구는 외부로부터 침입한 세균 등을 세포 내로 끌어들여 면역 반응에 가장 관계가 깊은 혈액 구성 물질입니다.', NOW(), 0),
(4, 1, '췌장의 랑게르한스섬에서 분비되는 호르몬은?', '인슐린', '글루카곤', '글루코겐', '에스트로겐', 1, '랑게르한스섬의 β 세포에서 분비되는 인슐린은 혈당을 낮추는 호르몬입니다.', NOW(), 0),
(5, 1, '비뇨기계에서 소변의 배출 순서를 바르게 표현한 것은?', '신장 - 요관 - 방광 - 요도', '신장 - 방광 - 요도 - 요관', '신장 - 요관 - 요도 - 방광', '신장 - 방광 - 요관 - 요도', 1, '소변의 배출 순서는 신장에서 생성된 소변이 요관을 통해 방광으로 운반되고, 방광에 저장된 소변이 요도를 통해 체외로 배출됩니다.', NOW(), 0),
(6, 1, '신장의 구조적, 기능적 단위는?', '세뇨관', '네프론', '말피기 소체', '사구체', 2, '네프론은 신장의 구조적, 기능적 기본 단위로, 사구체와 보우만주머니, 세뇨관으로 구성되어 혈액 여과, 재흡수, 분비 기능을 수행합니다.', NOW(), 0),
(7, 1, '순환기계 혈액 순서를 바르게 표현한 것은?', '우심실 - 대동맥 - 온몸 - 대정맥 - 좌심방', '좌심실 - 폐 - 폐 - 폐정맥 - 좌심방', '좌심실 - 대동맥 - 온몸 - 대정맥 - 우심방', '우심실 - 폐동맥 - 폐 - 폐정맥 - 좌심방', 4, '혈액은 우심실에서 폐동맥을 통해 폐로 이동하여 산소를 공급받고, 폐정맥을 통해 좌심방으로 돌아옵니다. 이것이 폐순환입니다.', NOW(), 0),
(8, 1, '다음중 말초신경계가 아닌 것은?', '뇌신경', '부교감신경', '척수', '척수신경', 3, '척수는 중추신경계에 속하며, 뇌와 함께 중추신경을 구성합니다. 말초신경계는 중추신경에서 나가는 뇌신경, 척수신경, 자율신경(교감신경, 부교감신경)으로 구성됩니다.', NOW(), 0),
(9, 1, '불수의근에 속하는 것은?', '인대', '골격근', '횡문근', '심근', 4, '심근은 심장을 구성하는 근육으로 불수의근입니다. 의식적으로 조절할 수 없으며 자동으로 수축하여 심장이 계속 뛰게 합니다. 반면 골격근과 횡문근은 수의근으로 의식적으로 조절 가능합니다.', NOW(), 0),
(10, 1, '간의 기능이 옳은 것은?', '단백질 합성', '대사작용', '담즙 생성', '해독작용', 1, '간은 단백질 합성, 탄수화물·지질·단백질 대사, 담즙 생성, 해독작용 등 다양한 기능을 수행합니다. 모두 간의 중요한 기능입니다.', NOW(), 0),
(11, 1, '랑게르한스섬에서 분비되는 글루카곤의 작용은?', '지방을 합성한다.', '소장에서 포도당의 흡수를 돕는다.', '담즙생성을 한다.', '글리코겐을 포도당으로 만든다.', 4, '글루카곤은 혈당을 상승시키는 호르몬으로, 글리코겐을 포도당으로 분해하여 혈당을 높입니다. 이는 인슐린과 반대의 작용을 합니다.', NOW(), 0),
(12, 1, '성인 정상인의 심장 박동수는?', '분당 80회', '분당 60회', '분당 50회', '분당 70회', 4, '성인의 정상 심장 박동수는 분당 60~100회이며, 평균적으로 분당 70회입니다.', NOW(), 0),
(13, 1, '보조개의 형성과 관계가 깊은 근은?', '대관골근', '구각하체근', '형근', '소근', 4, '보조개는 웃을 때 소근(zygomaticus minor)의 수축으로 인해 형성되는 움푹한 부분입니다.', NOW(), 0),
(14, 1, '성인의 골격은 모두 몇개인가?', '207개', '203개', '206개', '205개', 3, '성인의 골격은 총 206개입니다. 신생아는 약 270개의 뼈를 가지고 있지만, 성장하면서 뼈들이 융합되어 206개로 감소합니다.', NOW(), 0),
(15, 1, '성인의 뇌신경은 모두 몇 쌍인가?', '12쌍', '11쌍', '30쌍', '31쌍', 1, '성인의 뇌신경은 총 12쌍입니다. 척수신경은 31쌍이며, 뇌신경과 척수신경을 합쳐 말초신경을 구성합니다.', NOW(), 0),
(16, 1, '근육의 종류가 아닌것은?', '골격근', '협력근', '평활근', '심장근', 2, '근육의 종류는 골격근, 평활근, 심장근 3가지입니다. 협력근은 근육의 종류가 아니라 근육이 수행하는 역할/기능을 분류한 것입니다.', NOW(), 0),
(17, 1, '체내에 침입한 세균을 식균작용하는 것은?', '혈소판', '혈구', '적혈구', '백혈구', 4, '백혈구는 식균작용을 통해 체내에 침입한 세균, 바이러스, 이물질 등을 제거하여 면역 기능을 수행합니다.', NOW(), 0),
(18, 1, '림프를 바르게 설명한 것이 아닌것은?', '면역반응에 관여하지 않는다.', '림프는 림프관 속을 흐르는 액이다.', '조직액은 모세혈관으로 흡수되어 정맥으로 수농되거나 림프관을 통해서 운반된다.', '진신으로 나간 혈액이 모세혈관을 통해 조직의 대사물과 혼합돼 조직액을 형성한 것이다.', 1, '림프는 림프구를 포함하고 있어 면역반응에 적극적으로 관여합니다. 림프는 조직액에서 형성되어 림프관을 통해 순환합니다.', NOW(), 0),
(19, 1, '혈액중 헤모글로빈 성분의 역할은?', '무기질 운반', '영양소 운반', '노폐물 운반', '산소 운반', 4, '헤모글로빈은 적혈구에 포함된 단백질로, 산소와 결합하여 산소를 운반하는 주요 역할을 합니다.', NOW(), 0),
(20, 1, '다음 중 혈액의 기능이 아닌것은?', '산소와 이산화탄소의 운반에 의한 호흡 작용', '노폐물을 내보내는 배설작용', '영양분을 세포로 보내주는 운반 작용', '음식물을 위로 내려 보내는 수의적 작용', 4, '음식물을 위로 내려 보내는 것은 소화기계의 기능입니다. 혈액의 기능은 호흡, 배설, 운반, 체온조절, 방어 등입니다.', NOW(), 0),
(21, 1, '뇌하수체 전엽에서 분비되는 호르몬이 아닌것은?', '성장호르몬(GH)', '난포 자극 호르몬(FSH)', '갑상선 자극 호르몬(TSH)', '멜라노사이트 자극 호르몬(MSH)', 4, '멜라노사이트 자극 호르몬(MSH)은 뇌하수체 중엽에서 분비됩니다. GH, FSH, TSH는 뇌하수체 전엽에서 분비됩니다.', NOW(), 0),
(22, 1, '췌장에서 분비되는 트립신의 소화 효소의 작용이 바르게 연결되는것은?', '녹말 - 엿당', '단백질 - 펩톤', '지방 - 지방산, 글리세롤', '엿당 - 포도당', 2, '트립신은 단백질 분해 효소로, 단백질을 펩톤으로 분해합니다. 녹말은 아밀라아제, 지방은 리파아제, 엿당은 말타아제가 분해합니다.', NOW(), 0),
(23, 1, '조혈 기능이 있는 곳은?', '골막', '황골수', '골단', '적골구', 4, '조혈(혈액 생성) 기능은 적골수(red bone marrow)에서 일어나며, 적골구는 적골수를 의미합니다.', NOW(), 0),
(24, 1, '신경계의 기능으로 바른 것은?', '산소운반', '혈액 공급', '신체 보호 및 지지', '신체 조절 및 통제', 4, '신경계는 신체의 조절과 통제 기능을 담당합니다. 산소운반과 혈액공급은 순환계, 신체보호와 지지는 골격계의 기능입니다.', NOW(), 0),
(25, 1, '세포막을 경계로 압력차에 의하여 세포막을 통해 액체가 이동하는 물리적인 현상은?', '능동적 운반', '여과', '확산', '삼투', 2, '여과(filtration)는 압력차에 의해 물질이 세포막을 통해 이동하는 현상입니다. 능동적 운반은 에너지 필요, 확산과 삼투는 농도차에 의한 이동입니다.', NOW(), 0),
(26, 1, '골격근의 기능에 따른 명칭에 대한 설명 중 맞는 것은?', '굴근-운동 시 주된 역할을 하는 근육', '협력근-중근에 저항하여 자세를 유지하는데 작용하는 근육', '길항근-운동 시 반대의 작용을 하는 근육', '신근-굽힐때 사용하는 근육', 3, '길항근은 주동근의 반대 작용을 하는 근육입니다. 예를 들어 팔을 굽힐 때 이두근이 주동근이면 삼두근이 길항근입니다.', NOW(), 0),
(27, 1, '다음중 뼈의 구조가 아닌 것은?', '골막', '골질', '골수강', '심막', 4, '심막은 심장을 둘러싼 막으로 뼈의 구조가 아닙니다. 뼈의 구조는 골막, 골질(치밀골, 해면골), 골수강 등입니다.', NOW(), 0),
(28, 1, '핵에 대한 설명으로 틀린 것은?', '구조적, 기능적 최소 단위', '세포분열, 성장', '단백질 합성', '적혈구와 혈소판을 제외한 모든 세포에 존재', 1, '구조적, 기능적 최소 단위는 "핵"이 아니라 "세포"입니다. 핵은 유전정보를 담고 있으며 세포분열, 성장, 단백질 합성을 조절합니다.', NOW(), 0),
(29, 1, '성장기에 있어 뼈의 부피 성장이 일어나는 곳을 무엇이라 하는가?', '골아 세포', '골단판', '파골 세포', '연골 상골', 2, '골단판(epiphyseal plate)은 성장기 뼈의 길이 성장이 일어나는 부위입니다. 뼈의 부피 성장은 골막 아래에서 일어납니다.', NOW(), 0),
(30, 1, '혈액의 기능이 아닌것은?', '운반 기능', '조절 기능', '저장 기능', '보호 기능', 3, '혈액의 기능은 운반(산소, 영양소, 호르몬), 조절(호르몬), 보호(면역), 체온조절 등입니다. 저장 기능은 혈액의 기능이 아닙니다.', NOW(), 0),
(31, 1, '인체의 각 주요 호르몬의 기능 향진에 따라 나타나는 현상으로 틀린 것은?', '황체형성 자극 호르몬(LH) : 붙임', '난포 자극 호르몬(FSH): 사춘기 조기 발연', '부신피질 자극 호르몬(ACTH) : 혈중 칼슘 농도 증가', '성장 호르몬(GH) : 거인증', 3, 'ACTH는 부신피질 호르몬 분비를 자극하지만 혈중 칼슘 농도와는 직접적인 관련이 없습니다. 칼슘 농도는 부갑상선 호르몬(PTH)이 조절합니다.', NOW(), 0),
(32, 1, '성인의 척추의 개수로 바르게 표현한 것은?', '경추: 8개, 흉추: 11개, 요추: 4개, 천추: 1개, 미골: 5개', '경추: 7개, 흉추: 12개, 요추: 5개, 천추: 1개, 미골: 1개', '경추: 7개, 흉추: 11개, 요추: 4개, 천추: 5개, 미골: 3개', '경추: 8개, 흉추: 12개, 요추: 5개, 천추: 5개, 미골: 1개', 2, '성인의 척추는 경추 7개, 흉추 12개, 요추 5개, 천추 1개(융합), 미골 1개(융합)로 총 26개입니다.', NOW(), 0),
(33, 1, '다음 보기 사항에 해당되는 근육은? [보기] 눈을 둘러싸고 있어 뜬 눈의 크기를 조절하는 둥근모양의 괄약근', '이근', '소근', '안류근', '추미근', 3, '안류근(orbicularis oculi)은 눈 주위를 둘러싸고 있는 원형 근육으로 눈을 감는 역할을 합니다.', NOW(), 0),
(34, 1, '간의 기능으로 맞지 않는 것은?', '혈당량 조절', '체온 조절', '혈장 단백질 합성', '자방 소화 촉진', 4, '간은 혈당량 조절, 체온 조절, 혈장 단백질 합성, 담즙 생성 등의 기능을 합니다. 지방 소화는 담즙에 의해 촉진되며, 간의 직접적인 소화 기능은 아닙니다.', NOW(), 0),
(35, 1, '다음은 근육의 형태이다. 바르게 짝지어진 것은? [보기]\n| 세포의 형태 | 자율 신경계 지배 | 종류 |\n| --- | --- | --- |\n| (A) | 수의근 | 횡문근 |\n| 평활근 | (B) | 내장근 |\n| 심장근 | 불수의근 | (C) |', '골격근, 불수의근, 횡문근', '평활근, 수의근, 내장근', '심장근, 불수의근, 횡문근', '골격근, 수의근, 내장근', 1, '(A) 골격근은 수의근이며 횡문근입니다. (B) 평활근은 불수의근입니다. (C) 심장근은 불수의근이며 횡문근입니다.', NOW(), 0),
(36, 1, '세포에 대한 설명으로 틀린 것은?', '세포는 크게 핵, 세포질, 세포막의 세 구조로 이루어져 있다.', '세포내에는 핵이 핵막에 의해 둘러 싸여 있다.', '세포막은 원형질막 또는 선택적 투과막으로 불린다.', '세포막은 세포의 내부와 외부를 나눠줄 뿐 아니라 모든 물질을 유입시킨다.', 4, '세포막은 선택적 투과막으로 모든 물질을 유입시키지 않습니다. 필요한 물질만 선택적으로 통과시킵니다.', NOW(), 0),
(37, 1, '골격의 기능이 아닌 것은?', '조혈 기능', '저장 기능', '체혈 생산 기능', '운동 기능', 3, '골격의 기능은 조혈 기능(적골수에서 혈액 생성), 저장 기능(칼슘, 인 저장), 운동 기능(근육과 함께 움직임)입니다. 체혈 생산은 잘못된 표현입니다.', NOW(), 0),
(38, 1, '간의 기능에 대한 설명 중 틀린 것은?', '담즙 저장', '적혈구 파괴', '해독 작용', '영양소 저장', 1, '간은 담즙을 생성하지만 저장하지 않습니다. 담즙은 담낭에 저장되었다가 필요할 때 분비됩니다.', NOW(), 0),
(39, 1, '자연면역에 대한 설명으로 옳지 않은 것은?', '인체 내에 자연히 존재해 수동면역 이라 한다.', '기억세포의 작용은 없으나, 항원을 구분하여 저항할 수 있다.', '항원에 상관없이 모든 이물질에 대해 저항하여 비특이성면역 이라 한다.', '선천적으로 갖고 태어났다고 하여 선천면역이라 한다.', 1, '인체 내에 자연히 존재하는 면역은 자연면역(선천면역)입니다. 수동면역은 외부에서 항체를 받는 면역으로, 모체로부터 받는 항체나 항혈청 주사 등이 해당됩니다.', NOW(), 0),
(40, 1, '다음중 메라닌의 형성과정이 바르게 표시된 것은?', '티로신 - 도파 - 도파퀴논 - 도파크롬 - 멜라닌 형성', '도파 - 도파퀴논 - 도파크롬 - 티로신 - 멜라닌 형성', '도파퀴논 - 도파크롬 - 티로신 - 도파 - 멜라닌 형성', '도파크롬 - 티로신 - 도파 - 도파퀴논 - 멜라닌 형성', 1, '멜라닌 합성 경로는 티로신에서 시작하여 도파, 도파퀴논, 도파크롬을 거쳐 멜라닌이 형성됩니다.', NOW(), 0),
(41, 1, '다음 중 외분비샘이 아닌 것은?', '갑상선샘', '침샘', '위샘', '땀샘', 1, '갑상선은 내분비샘으로 호르몬을 혈액으로 직접 분비합니다. 침샘, 위샘, 땀샘은 외분비샘으로 관을 통해 분비물을 배출합니다.', NOW(), 0),
(42, 1, '다음 중 내인성 노화에서 표피의 변화가 맞는 것은?', '교원질의 총량 감소', '기질성분 감소', '탄력섬유의 가교의 증', '링게르한스 세포수 감소', 4, '내인성 노화에서 표피의 변화는 링게르한스 세포와 멜라닌 세포의 감소입니다. 1~3번은 진피의 변화입니다.', NOW(), 0),
(43, 1, '손, 발톱에 피부사상균이 침입하여 일으키는 질환으로, 광택을 잃고 변하거나 부스러지며 울퉁불퉁해 지는 질환은 무엇인가?', '족부백선', '조갑백선', '수부백선', '체부백선', 2, '조갑백선은 손톱과 발톱에 피부사상균이 침입하여 발생하는 질환으로 광택을 잃고 변색, 부스러짐, 울퉁불퉁함이 특징입니다.', NOW(), 0),
(44, 1, '다음의 특징을 가장 잘 나타낸 것은? [보기]\n- 표피와 피하조직 사이에 위치하는 강하고 유연성 있는 결합조직이다.\n- 피부의 90%를 차지하며 표피의 약 10~40배에 해당하는 실직적인 피부다.\n- 유두층과 망상층으로 구분할 수 있다.\n- 혈관(림프관)이 흐르고 피부신경들이 위치하고 있다.', '표피', '진피', '피하조직', '피부의 색', 2, '진피는 피부의 90%를 차지하며 표피의 약 10~40배 크기입니다. 유두층과 망상층으로 구분되고, 혈관, 림프관, 신경이 위치합니다.', NOW(), 0),
(45, 1, '각질층의 기능으로 틀린 것은?', '외부의 독성물질이나 물리적 충격 등에 대한 생체 방어 기능을 한다.', '각질층의 수분함량이 10% ~ 20% 정도 이면 정상상태 이다.', '수분의 증발을 억제하고 피부의 탄력성유지와 손상방지 역할을 한다.', '과다한 수분 침투를 방지하고 피부를 윤기있게 해준다.', 2, '각질층의 수분함량 정상 범위는 10~30%입니다. 10~20%는 건조한 상태에 해당합니다.', NOW(), 0),
(46, 1, '다음 중 단백질이 피부건강에 미치는 효과로 옳은 것은?', '피부의 저항력을 감소시켜 피부 트러블의 원인이 된다.', '피부보습에 도움을 주나 각화과정에는 관여하지 않는다.', '피부의 윤기와 탄력을 증진시킨다.', '손톱과 발톱건강에만 관여하며 성장과는 무관하다.', 3, '단백질은 콜라겐과 엘라스틴의 주요 성분으로 피부의 윤기와 탄력을 증진시키며, 피부 건강 유지에 필수적입니다.', NOW(), 0),
(47, 1, '나이가 들어감에 따라 나타나는 자연적 노화현상을 무엇이라 하는가?', '외인성 노화', '내인성 노화', '진피의 노화', '표피의 노화', 2, '내인성 노화는 시간 경과에 따른 자연적 노화 현상으로, 유전, 세포 분열 한계, 호르몬 변화 등으로 인해 발생합니다.', NOW(), 0),
(48, 1, '다음 중 면역반응에 대한 설명으로 옳지 않은 것은?', '면역반응이 일어날 때에는 체액성 면역이나 세포성면역 둘 중 하나만이 작용한다.', '외부침입물질을 제거하는 면역은 크게 세포성면역과 체액성면역으로 나뉜다.', '체액성면역은 B세포가 발하는 항체가 주체가되어 항원을 제거하는 반응이다.', '세포성면역은 킬러 T세포 와 대식세포 들이 주체가 되어 항원을 제거하는 반응이다.', 1, '면역반응이 일어날 때 체액성 면역과 세포성 면역은 함께 작용합니다. 둘 중 하나만 작용하지 않습니다.', NOW(), 0),
(49, 1, '자외선 자체가 면역력을 일으켜 발생하는 발진으로, 주로 봄에 젊은 사람에게 소수포의 형태로 잘 나타나는 광선에 대한 과민반응은?', '다형광발진', '광독성 피부염', '일광 두드러기', '일광 알레르기', 1, '다형광발진은 자외선에 대한 과민반응으로 봄에 젊은 사람에게 소수포 형태로 나타나는 질환입니다.', NOW(), 0),
(50, 1, '다음 중 영양에 대해서 가장 잘 설명한 것은?', '음식물로부터 우리 몸에 필요한 50여종 이상의 섭취한 화학 물질이다.', '우리 몸의 정상적인 생리기능을 원활하게 하는 물질로 소화, 흡수 한다.', '기능에 따라 열량영양소, 구성영양소, 조절영양소로 구분한다.', '섭취한 물질을 통해서 건강과 생명을 유지하는 것을 영양이라 한다.', 4, '영양은 섭취한 물질을 통해 건강과 생명을 유지하는 것입니다. 1번은 영양소의 정의, 2번은 소화흡수의 정의, 3번은 영양소의 분류입니다.', NOW(), 0),
(51, 1, '표피(Epidermis)의 기능에 대한 설명으로 옳은 것은?', '피부를 재생하는 기능을 한다.', '피부의 제일 바깥층으로서 산성보호막(Acid Mantle)과 함께 외부환경에 대한 첫번째 방어막 역할을 한다.', '피부의 손상으로부터 인체를 보호하고 수분저장, 체온조절, 감각수용체 역할을 한다.', '피부의 탄력, 균형, 긴장도, 윤기 등을 부여한다.', 2, '표피는 피부의 가장 바깥층으로 산성보호막과 함께 외부환경에 대한 첫 번째 방어막 역할을 합니다.', NOW(), 0),
(52, 1, '피부질환에 대한 설명으로 옳은 것은?', '개인의 체질이나 환경에 관계없이 동일한 증세가 나타난다.', '원발진과 속발진으로 구분된다.', '피부질환의 일반적 형태로서 가장 1차적 피부장애증상을 속발진 이라 한다.', '2차적으로 다른 요인에 의해 나타나는 피부질환을 원발진이라 한다.', 2, '피부질환은 원발진(1차 증상)과 속발진(2차 증상)으로 구분됩니다. 원발진은 질환의 기본 증상이고, 속발진은 원발진이 진행되면서 나타나는 증상입니다.', NOW(), 0),
(53, 1, '면역체계 이상시의 반응으로 옳지 않은 것은?', '인체의 자연치유 능력 강화', '자가면역질환', '후천성면역결핍증', '바이러스 침투용이', 1, '면역체계 이상은 자연치유 능력을 약화시킵니다. 강화되지 않으며, 자가면역질환, 후천성면역결핍증, 바이러스 침투 용이 등이 발생합니다.', NOW(), 0),
(54, 1, '다음 중 노화의 기초요인에 속하지 않는 것은?', '불안', '슬픔', '음식제한', '공포', 3, '노화의 기초요인은 불안, 슬픔, 공포 등의 정서적 요인입니다. 음식제한은 노화를 촉진하는 요인이지만 기초요인이 아닙니다.', NOW(), 0),
(55, 1, '면역과 피부의 관계를 설명한 것 중 옳은 것은?', '피부는 인체를 방어하고 있는 최초의 위치에 있다.', '피부는 외부의 자극물질을 차단시키며 방어체계가 무너졌을 때 즉시 반응을 보이는 곳 이다.', '면역은 피부의 구조와 분비액 등에는 영향을 미치지 않는다.', '면역은 스트레스 등과 같은 자극이나 자율신경계와는 관계가 없다.', 1, '피부는 인체를 방어하고 있는 최초의 위치에 있으며, 외부 자극물질을 차단하고 방어체계가 무너졌을 때 즉시 반응을 보입니다.', NOW(), 0),
(56, 1, '아토피피부염의 발생 원인으로 틀린 것은?', '집먼지진드기, 동물의 털이나 분비물, 꽃가루, 곰팡이 등과 같이 알레르기성 질환의 환경적인 영향을 많이 받는다.', '아토피는 유전적인 체질과 관계가 깊고, 스트레스로 인한 호르몬의 자극도 영향이 있다.', '지나친 목욕, 과도한 비누사용, 각종 화학섬유 등도 아토피피부염의 원인이 될 수 있다.', '아토피피부염의 예방으로 좋은 음식으로 우유나 계란, 밀가루 과자 등이 있다.', 4, '우유, 계란, 밀가루 등은 알레르기 유발 식품으로 아토피피부염을 악화시킬 수 있습니다. 예방 음식이 아닙니다.', NOW(), 0),
(57, 1, '표피의 구성세포로서 옳지 않은 것은?', '랑게르한스세포', '멜라닌형성세포', '머켈세포', '비만세포', 4, '비만세포는 진피에 존재하며, 표피의 구성세포가 아닙니다.', NOW(), 0),
(58, 1, '각질층의 특징으로 옳은 것은?', '생명력이 없는 2~3층의 얇고 투명한 무핵의 평면 세포로서 손바닥, 발바닥 등에서 잘 관찰된다.', '표피의 가장 바깥쪽의 무핵세포이며 20~30개의 세포층으로서 라멜라 구조로 되어 있고 주성분은 케라틴, 천연보습인자 및 지질 등이다.', '엘라딘 이라는 반 유동성 단백질이 들어 있어 투명하게 보인다.', '세포분열이 일어나므로 피부손상을 복구할 수 있다.', 2, '각질층은 20~30층의 무핵 세포로 라멜라 구조를 가지며, 케라틴, NMF, 지질로 구성됩니다.', NOW(), 0),
(59, 1, '표피의 특징에 대한 설명 중 옳은 것은?', '표피는 무핵의 각질층, 투명층과 유핵의 과립층, 유극층, 기저층으로 나눈다.', '표피는 무핵의 각질층, 투명층, 과립층과 유핵의 유극층, 기저층으로 나눈다.', '투명층은 손바닥과 발바닥에만 존재한다.', '유극층은 표피의 맨 밑에 존재하며 각질형성세포와 멜라닌 형성세포를 포함하고 있다.', 2, '표피는 무핵의 각질층, 투명층, 과립층과 유핵의 유극층, 기저층으로 구성됩니다.', NOW(), 0),
(60, 1, '다음 중 피부의 기능이 아닌 것은?', '지지작용', '비타민D 합성 작용', '저장작용', '보호작용', 1, '지지작용은 뼈와 근육의 기능이며, 피부의 기능이 아닙니다.', NOW(), 0),
(61, 1, '천연보습인자(NMF)에 대한 설명으로 옳지 않은 것은?', '수분의 증발을 막는다.', '아미노산, 피롤리딘카르복실산, 젖산, 요소 등으로 구성되어 있다.', '세라마이드, 지방산, 콜레스테롤이 있는 2중층의 친유기 집단의 형태이다.', '미생물과 오염물질의 피부침투를 막는다.', 3, '세라마이드 등 지질층의 라멜라 구조에 대한 설명입니다. NMF는 수용성 물질입니다.', NOW(), 0),
(62, 1, '멜라닌형성세포의 특징이 아닌 것은?', '기저층에 존재하며 피부색을 결정한다.', '멜라닌세포의 수는 인종과 피부색에 따라 다르다.', '피부색은 멜라닌 색소의 양과 크기에 따라 결정된다.', '멜라닌색소의 양이 적으면 흰 피부, 많으면 흑갈색의 피부가 된다.', 2, '멜라닌세포의 수는 인종과 관계없이 거의 같습니다. 피부색 차이는 멜라닌의 양과 활성도에 따릅니다.', NOW(), 0),
(63, 1, '다음 중 피부와 영양에 대해서 옳은 것은?', '피부에는 식물성 단백질이 동물성 단백질보다 더 좋다.', '피부의 건강에 대한 영양은 화장품이나 의약품으로부터 공급받는 것이 좋다.', '피부를 좋게 하려면 혈액이 산성에 가깝도록 하는 음식물을 섭취하면 좋다.', '1일 필요단백질의 3분의 1은 동물성 단백질을 섭취하면 좋다.', 4, '1일 필요단백질의 1/3은 동물성 단백질 섭취가 권장됩니다.', NOW(), 0),
(64, 1, '알레르기성 접촉피부염의 설명으로 틀린 것은?', '정확한 원인 물질의 규명을 위해서 첩포시험을 실시한다.', '외부 물질과 닿은 후에 늦게 나타나며 가려움증, 구진, 반점 등의 증세가 나타난다.', '자극물질이 직접 닿았던 부위뿐만 아니라 일정한 농도의 자극을 주면 모든 사람에게 발생된다.', '피부 병변의 관찰에는 발생부위와 발진의 모양도 원인 물질의 발견에 매우 중요하다.', 3, '이것은 자극성 접촉피부염의 설명입니다. 알레르기성은 감작된 사람에게만 발생합니다.', NOW(), 0),
(65, 1, '다음 중 노화의 증상으로 볼 수 없는 것은?', '쉽게 피로해지며 체력과 근력이 떨어진다.', '피부는 탄력이 증대되고 혈액순환 등이 좋아진다.', '시력이 나빠지거나 기억력이 감퇴되는 자각증세를 느낀다.', '흰머리가 생기고, 머리카락이 빠지기도 한다.', 2, '노화 시 피부는 탄력이 감소되고 혈액순환이 나빠집니다.', NOW(), 0),
(66, 1, '피부 노화의 분류와 나타나는 특징의 연결이 옳지 않은 것은?', '내인성 노화: 표피두께 감소, 탄력섬유 감소, 지방조직 감소', '내인성 노화: 표피두께 감소, 각질 일어남, 교원섬유 감소', '외인성 노화: 멜라닌세포수 증가, 혈관 확장, 랑게르한스세포 증가', '외인성 노화: 멜라닌세포수 증가, 혈관 확장, 랑게르한스세포 감소', 3, '외인성 노화에서 랑게르한스세포는 자외선 손상으로 인해 감소합니다.', NOW(), 0),
(67, 1, '세균이나 바이러스 등으로 인한 질환이나 질병으로부터 저항할 수 있는 인체의 능력을 무엇이라 하는가?', '항원', '항체', '알레르기', '면역', 4, '면역은 병원체로부터 신체를 보호하는 인체의 방어 능력입니다.', NOW(), 0),
(68, 1, '다음 중 피부노화의 현상으로 틀린 것은?', '피부주름 생성', '피부 처짐과 탄력 감소', '피부 색소 침착', '피부 탄력 증가와 피지분비 증가', 4, '노화 시 피부는 탄력이 감소하고 피지분비도 감소합니다.', NOW(), 0),
(69, 1, '다음 중 피부 구조에 대한 설명으로 옳지 않은 것은?', '성인의 경우 피부는 신체무게의 20%를 차지하는 넓은 면적이고, 펼쳐놓으면 1.6m2 정도 된다.', '눈꺼풀의 경우 1.9mm로 두께가 얇고 허벅지는 약 9mm의 두께를 지니고 있다.', '피부는 모체에서 뇌와 함께 형성되며 신체의 가장 겉면에 있다.', '피부는 수분과 지방, 단백질 및 무기질로 이루어져 있는데 이러한 성분들은 피부 조직의 생리현상과 같다.', 4, '피부의 성분들은 피부 조직의 생리현상과 다릅니다.', NOW(), 0),
(70, 1, '다음 중 노화의 억제요인으로 볼 수 없는 것은?', '비효율적 대처', '음식제한', '활동수준', '신체활동', 1, '비효율적 대처는 노화를 촉진하는 요인입니다.', NOW(), 0),
(71, 1, '세포노화의 설명으로 바른 것은?', '사람의 몸은 세균처럼 빨리 분열하지 않는다.', '중년 이전에 뇌나 콩팥의 무게가 감소한다.', '세포는 꾸준히 세포 분열을 한다.', '인공적으로 적당한 조직이라도 세포를 배양하거나 무제한 배양을 거듭할 수는 없고 50대가 되면 분열이 정지된다.', 4, '헤이플릭 극한: 세포는 약 50회 분열 후 정지됩니다.', NOW(), 0),
(72, 1, '피하지방층의 기능으로 알맞은 것은?', '남성호르몬과 관계가 깊다.', '각질을 형성한다.', '신진대사를 조절하는데 필요한 필수지방산을 공급한다.', '랑게르한스세포가 존재한다.', 3, '피하지방층은 필수지방산을 공급하여 신진대사를 조절합니다.', NOW(), 0),
(73, 1, '한선에 대한 설명 중 옳은 것은?', '에포크린한선은 입술과 음부를 제외하고 신체 모든 부위에 분포되어있다.', '에크린한선을 소한선이라고 한다.', '땀의 분비가 적어지는 것을 다한증이라고 한다.', '에크린한선은 감정의 변화가 있을 때 더욱 활발한 작용을 한다.', 2, '에크린한선을 소한선이라고 합니다.', NOW(), 0),
(74, 1, '피하지방층에 대한 설명으로 틀린 것은?', '외부로부터의 충격을 흡수하여 신체를 보호한다.', '단열제 역할을 해서 체온을 유지해 준다.', '피부재생에도 관여할 수 있다.', '잉여의 영양소를 저장한다.', 3, '피부재생은 표피의 기저층에서 주로 일어납니다.', NOW(), 0),
(75, 1, '수용성 비타민으로 옳게 짝지어진 것은?', '비타민A, 비타민C', '비타민A, 비타민B1', '비타민C, 비타민B12', '비타민D, 비타민K', 3, '비타민C와 B12는 모두 수용성 비타민입니다.', NOW(), 0),
(76, 1, '지용성 비타민의 설명 중 잘못 연결된 것은?', '비타민E - 피부노화 방지와 상처 치유에 효과를 끼친다.', '비타민K - 항산화성 비타민이다.', '비타민D - 치아, 골격 형성에 특히 중요하다.', '비타민A - 상피조직을 보호한다.', 2, '비타민K는 지혈 작용이 주요 기능이며, 항산화성은 비타민E입니다.', NOW(), 0),
(77, 1, '무기질에 대한 다음 설명 중 잘못된 것은?', '칼슘 : 골격과 치아를 구성한다.', '나트륨 : 삼투압을 조절하고 근육 기능과 관련된다.', '인 : 결핍되면 갑상선기능저하증을 유발한다.', '철 : 결핍되면 빈혈이 생긴다.', 3, '요오드 결핍이 갑상선기능저하증을 유발합니다. 인은 에너지 대사와 관련됩니다.', NOW(), 0),
(78, 1, '다음 중 각 영양소가 피부에 미치는 효과에 대한 설명 중 옳은 것은?', '단백질 : 체온조절기능과 피지선 기능을 조절한다.', '비타민 : 과잉섭취 시 피하지방에 축척되어 비만을 초래한다.', '지방 : 피부 재생작용에 대부분 사용된다.', '탄수화물 : 과잉섭취 시 피지분비가 촉진되어 지성피부가 되기도 한다.', 4, '탄수화물 과잉 섭취 시 피지분비가 촉진되어 지성피부가 될 수 있습니다.', NOW(), 0),
(79, 1, '피부표면에서 분비되는 피지에 대한 설명 중 옳지 않은 것은?', '피지 속에 있는 지방산은 향균 기능이 있으므로 지방산이 많으면 많을수록 좋다.', '피지의 분비가 적으면 피부가 거칠어지고 건조해진다.', '피부표면에 얇은 지방막을 형성하며 피부에 윤기를 준다.', '목욕, 세안 후 유성크림을 바르는 것은 인공의 지방막을 형성하게 하여 피부를 보호하기 위함이다.', 1, '지방산이 많으면 산화되어 악취와 여드름 등의 문제가 발생합니다. 적절한 양이 중요합니다.', NOW(), 0),
(80, 1, '다음 중 영양소를 잘못 분류된 것은?', '3대 영양소 : 탄수화물, 지방, 단백질', '5대 영양소 : 탄수화물, 지방, 단백질, 무기질, 비타민', '6대 영양소 : 탄수화물, 지방, 단백질, 무기질, 비타민, 식이섬유', '7대 영양소 : 탄수화물, 지방, 단백질, 무기질, 비타민, 물, 식이섬유', 4, '물은 6대 영양소에 포함되지 않습니다. 6대는 탄수화물, 지방, 단백질, 무기질, 비타민, 식이섬유입니다.', NOW(), 0);
